content.text:
            packetRows.addAll(dr.packets);
            datagramRows.add(dr.row);
        }
    }
    return result();
}

DatagramResult processDatagram(int event, Main.Event ev) {
    List<Map<String,Object>> rows = new ArrayList<>();
    MessageDigest dg;
    try { dg = MessageDigest.getInstance("SHA-256"); }
    catch (Exception e) { throw new RuntimeException(e); }

    int attempt = 0, pos = 0;
    long accepted = 0, bytes = 0;
    byte[] wire = ev.wire == null ? EMPTY : ev.wire;

    while (pos < wire.length) {
        Header h;
        try {
            h = parseHeader(wire, pos, localCidWidth);
        } catch (BadHeader bh) {
            rows.add(packetRow(event, attempt, pos, null, null, null, "BAD_HEADER", null));
            attempt++;
            break; // BAD_HEADER abandons this datagram remainder
        }

        long expected = receivedLargest[h.level] < 0 ? 0 : receivedLargest[h.level] + 1;
        long pn = reconstructPn(expected, h.pnWidth, h.rawPn);
        PacketOutcome out = processPacket(event, attempt, h, pn, expected, ev.auth);
        rows.add(packetRow(event, attempt, pos, h.level, pn, out.epoch, out.status,
                out.accepted ? shaHex(out.canonical) : null));
        if (out.accepted) {
            accepted++;
            bytes += out.canonical.length;
            dg.update(out.canonical);
        }
        attempt++;

        if (h.level == A) break;
        pos = h.nextPos;
    }

    Map<String,Object> row = obj(
            "event", event,
            "packets", (long)rows.size(),
            "accepted", accepted,
            "bytes", bytes,
            "sha256", Main.hex(dg.digest()));
    DatagramResult dr = new DatagramResult();
    dr.row = row; dr.packets = rows;
    return dr;
}

Map<String,Object> packetRow(int event, int packet, int offset, Integer level,
                             Long pn, Long epoch, String status, String sha) {
    return obj("event", event, "packet", packet, "offset", offset,
            "level", level == null ? null : LEVEL_NAME[level],
            "pn", pn, "epoch", epoch, "status", status, "sha256", sha);
}

boolean authAllowedA(long gen, int phase) {
    if (gen < 0) return false;
    boolean window = gen == keyEpoch
            || (keyEpoch > 0 && gen == keyEpoch - 1)
            || (keyEpoch < MAX_PN && gen == keyEpoch + 1);
    if (!window) return false;
    return (gen & 1L) == (long)phase;
}

boolean epochOrderViolation(long gen, long pn) {
    // Every packet in a higher epoch must be strictly larger than every packet
    // in a lower epoch.  This packet is the only new member of gen.
    for (Map.Entry<Long,EpochStats> e : epochs.entrySet()) {
        long ep = e.getKey(); EpochStats s = e.getValue();
        if (s.count == 0) continue;
        if (ep < gen) {
            if (s.max >= pn) return true;
        } else if (ep > gen) {
            if (s.min <= pn) return true;
        }
    }
    return false;
}

PacketOutcome processPacket(int event, int packet, Header h, long pn,
                            long expectedBefore, List<Long> authList) {
    PacketOutcome out = new PacketOutcome();
    out.level = h.level; out.pn = pn; out.epoch = null;

    if (closed != null) { out.status = "CLOSED"; return out; }

    Integer destSeqObj = localCidSeq.get(new ByteKey(h.destination));
    if (destSeqObj == null || retiredLocal.contains(destSeqObj.longValue())) {
        out.status = "DROP_CID"; return out;
    }
    int destSeq = destSeqObj;

    if (!keys[h.level]) { out.status = "NO_KEY"; return out; }
    if (pn > MAX_PN) { out.status = "PN_RANGE"; return out; }

    Long auth = authList != null && packet < authList.size() ? authList.get(packet) : null;
    Long annEpoch = null;
    if (h.level == A) {
        if (auth == null || !authAllowedA(auth, h.phase)) {
            out.status = "AUTH"; return out;
        }
        annEpoch = auth;
        out.epoch = annEpoch;
    } else {
        // Initial and Handshake have generation 0 only.
        if (auth == null || auth.longValue() != 0L) {
            out.status = "AUTH"; return out;
        }
    }

    if (seen[h.level].contains(pn)) { out.status = "DUPLICATE"; return out; }

    if (h.level == A && epochOrderViolation(annEpoch, pn)) {
        out.status = "KEY_UPDATE_ERROR";
        closed = new ClosedInfo(event, packet, 0, out.status);
        return out;
    }

    PacketTxn tx = new PacketTxn(this);
    FrameResult fr;
    try {
        fr = processFrames(h.level, h.payload, tx, destSeq);
    } catch (FrameFailure f) {
        tx.rollback();
        out.status = f.status;
        closed = new ClosedInfo(event, packet, f.offset, f.status);
        return out;
    }

    // All frame effects are now known to be successful.
    tx.commitAckAndRetire();

    // Only successful packets advance PN/epoch history.
    seen[h.level].add(pn);
    if (receivedLargest[h.level] < 0 || pn > receivedLargest[h.level])
        receivedLargest[h.level] = pn;
    if (h.level == A) {
        EpochStats es = epochs.get(annEpoch);
        if (es == null) epochs.put(annEpoch, new EpochStats(pn));
        else {
            if (pn < es.min) es.min = pn;
            if (pn > es.max) es.max = pn;
            es.count++;
        }
        if (annEpoch == keyEpoch + 1 && keyEpoch < MAX_PN) keyEpoch = annEpoch;
    }

    byte[] canonical = canonicalize(h, pn, expectedBefore, fr.payload);
    out.canonical = canonical;
    out.accepted = true;
    out.status = fr.closed ? "PEER_CLOSE" : "OK";
    if (fr.closed) closed = new ClosedInfo(event, packet, fr.closeOffset, "PEER_CLOSE");
    return out;
}

// -----------------------------------------------------------------
// Frame decoding, validation and canonical reconstruction
// -----------------------------------------------------------------
FrameResult processFrames(int level, byte[] payload, PacketTxn tx, int destSeq) throws FrameFailure {
    if (payload.length == 0) throw new FrameFailure("FRAME_ENCODING_ERROR", 0);
    ByteBuf out = new ByteBuf();
    int pos = 0;

    while (pos < payload.length) {
        int start = pos;
        Varint tv = tryVarint(payload, pos);
        if (tv == null) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
        if (tv.width != minVarintWidth(tv.value))
            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
        long type = tv.value;
        pos = tv.next;
        if (!supportedFrame(type)) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
        checkFrameLevel(type, level, start);
        writeVarint(out, type);

        BodyCursor b = new BodyCursor(payload, pos, start);
        switch ((int)type) {
            case 0x00:
            case 0x01:
                break;

            case 0x02:
            case 0x03: {
                long largest = b.v(); writeVarint(out, largest);
                long delay = b.v(); writeVarint(out, delay);
                long count = b.v(); writeVarint(out, count);
                long first = b.v(); writeVarint(out, first);
                if (first > largest) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                if (count > (long)(payload.length - b.pos) / 2L)
                    throw new FrameFailure("FRAME_ENCODING_ERROR", start);

                List<long[]> frameRanges = new ArrayList<>();
                long low = largest - first;
                frameRanges.add(new long[]{low, largest + 1});
                for (long i = 0; i < count; i++) {
